BASE = "http://pricing-v2.internal:8081/api/v2/price"


def get_price(sku: str) -> float:
    request = urllib.request.Request(
        f"{BASE}/{urllib.parse.quote(sku, safe='')}",
        headers={"X-Pricing-Key": os.environ.get("PRICING_API_KEY", "pk-7f3a91")},
    )
    with urllib.request.urlopen(request, timeout=5) as r:
        return float(json.load(r)["unit_price"])


def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
